parameters.jsCode:
// Assemble a single context object for one Gemini call.
const t = $('03 - Normalize Input').first().json;
const branches = $input.all().map(i => i.json);

// Branch A/B/C arrive appended in order; guard against missing rows.
const profile = branches[0] || {};
const history = branches.filter(b => b && b.ticket_id).slice(0, 5);
const account = branches.find(b => b && (b.plan || b.account_status || b.is_lead !== undefined)) || {};

const contextText = [
  '### Customer Profile', JSON.stringify(profile),
  '### Recent Tickets (max 5)', JSON.stringify(history),
  '### Account / Order / Lead', JSON.stringify(account),
].join('\n');

return [{
  json: {
    ticket_id: t.ticket_id,
    customer_id: t.customer_id,
    name: t.name,
    email: t.email,
    subject: t.subject,
    message: t.message,
    incoming_priority: t.priority,
    request_type: t.request_type,
    context_text: contextText,
  },
}];

