parameters.jsCode:
const ctx = $('06 - Prepare AI Context').first().json;
const item = $input.first().json;
const raw = item.output || item;

const required = ['category','priority','intent','recommended_action','auto_resolve','escalate','customer_response','internal_summary','lead'];
const valid = raw && typeof raw === 'object' && required.every(k => k in raw);

// Read real Gemini/LangChain usage metadata when the node exposes it. No extra API call. Never fabricate numbers.
const usage = item.tokenUsage || item.usage || item.usageMetadata || (item.response_metadata && item.response_metadata.tokenUsage) || {};
const inputTokens = usage.promptTokens ?? usage.input_tokens ?? usage.promptTokenCount ?? usage.inputTokens ?? null;
const outputTokens = usage.completionTokens ?? usage.output_tokens ?? usage.candidatesTokenCount ?? usage.outputTokens ?? null;
const totalTokens = usage.totalTokens ?? usage.total_tokens ?? usage.totalTokenCount ?? ((inputTokens != null && outputTokens != null) ? (inputTokens + outputTokens) : null);

return [{
  json: {
    valid,
    ai: valid ? raw : null,
    ticket_id: ctx.ticket_id,
    customer_id: ctx.customer_id,
    name: ctx.name,
    email: ctx.email,
    subject: ctx.subject,
    execution_id: $execution.id,
    model: 'models/gemini-2.5-flash',
    input_tokens: inputTokens != null ? inputTokens : '',
    output_tokens: outputTokens != null ? outputTokens : '',
    total_tokens: totalTokens != null ? totalTokens : '',
    timestamp: new Date().toISOString(),
    status: valid ? 'success' : 'ai_parse_failed',
  },
}];

